"""CARIBOU — Display the dataset summary and histogram generated by describe_missions."""

from hashlib import sha256
import streamlit as st

from caribou_data.description import describe_view


def render_description(frame, context):
    """Generate and display a description for the current filtered view."""
    st.subheader("Dataset description")
    st.caption(
        "Generate a table by year and overall, plus an emissions histogram, for the current filtered "
        "view. Missions without a team are retained but do not count as an extra team. Simulation "
        "excludes them. Changing the filters or histogram bins requires generating the description again."
    )
    labels = {}
    for value in frame["mission_type"].fillna(""):
        label = str(value).strip()
        if label:
            labels.setdefault(label.casefold(), label)
    excluded = st.multiselect(
        "Exclude mission types from the table and histogram",
        options=sorted(labels.values()),
        key=context + "-description-exclusions",
        help="Matches complete labels, ignoring capitalization and surrounding whitespace. "
        "Combined labels remain included unless explicitly selected. "
        "This only affects the dataset description, not the workbook, other charts or simulations.",
    )
    excluded_keys = {value.casefold() for value in excluded}
    excluded_mask = frame["mission_type"].fillna("").astype(str).str.strip().str.casefold().isin(excluded_keys)
    frame = frame.loc[~excluded_mask].copy()
    if excluded:
        st.caption(f"{int(excluded_mask.sum())} missions excluded; {len(frame)} missions retained.")
    if frame.empty:
        st.info("No missions remain for the dataset description.")
        return
    bins = st.number_input(
        "Histogram bins",
        min_value=1,
        max_value=200,
        value=30,
        step=1,
        key=context + "-description-bins",
    )
    signature = sha256(
        (frame.to_json(date_format="iso", orient="split") + str(bins)).encode()
    ).hexdigest()
    result_key = context + "-description-result"
    if st.button("Generate dataset description", key=context + "-description-generate"):
        st.session_state.pop(result_key, None)
        try:
            with st.spinner("Generating dataset table and histogram…"):
                files = describe_view(frame, int(bins))
            st.session_state[result_key] = (signature, files)
        except Exception as exc:
            st.error(f"Unable to describe missions: {exc}")
    saved = st.session_state.get(result_key)
    if saved is None or saved[0] != signature:
        return
    files = saved[1]
    st.markdown(files["table_dataset.md"].decode("utf-8"), unsafe_allow_html=False)
    st.image(files["fig_emissions_histogram.png"])
    for name, content in files.items():
        mime = (
            "image/png"
            if name.endswith(".png")
            else (
                "application/pdf"
                if name.endswith(".pdf")
                else "text/markdown" if name.endswith(".md") else "text/plain"
            )
        )
        st.download_button(
            "Download " + name,
            content,
            file_name=name,
            mime=mime,
            key=context + "-description-" + name,
        )
